    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int c;
            cin >> c;
            --c; // 0-index
            cntClassColor[(i + j) % 3][c]++;
        }
    }

    // cost[g][newColor] = total wrongness to repaint all cells in group g to newColor
    vector<vector<long long>> cost(3, vector<long long>(C, 0));
    for (int g = 0; g < 3; ++g) {
        for (int newColor = 0; newColor < C; ++newColor) {
            long long sum = 0;
            for (int oldColor = 0; oldColor < C; ++oldColor) {
                sum += 1LL * cntClassColor[g][oldColor] * D[oldColor][newColor];
            }
            cost[g][newColor] = sum;
        }
    }

    long long ans = (1LL << 62);
    for (int c0 = 0; c0 < C; ++c0) {
        for (int c1 = 0; c1 < C; ++c1) {
            if (c1 == c0) continue;
            for (int c2 = 0; c2 < C; ++c2) {
                if (c2 == c0 || c2 == c1) continue;
                ans = min(ans, cost[0][c0] + cost[1][c1] + cost[2][c2]);
            }
        }
    }

    cout << ans << '\n';
    return 0;
