public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int C = fs.nextInt();

        int[][] D = new int[C][C];
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                D[i][j] = fs.nextInt();
            }
        }

        int[][] count = new int[3][C];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int color = fs.nextInt() - 1;
                count[(i + j) % 3][color]++;
            }
        }

        long[][] cost = new long[3][C];
        for (int group = 0; group < 3; group++) {
            for (int newColor = 0; newColor < C; newColor++) {
                long sum = 0;
                for (int oldColor = 0; oldColor < C; oldColor++) {
                    sum += (long) count[group][oldColor] * D[oldColor][newColor];
                }
                cost[group][newColor] = sum;
            }
        }

        long ans = Long.MAX_VALUE;
        for (int c0 = 0; c0 < C; c0++) {
            for (int c1 = 0; c1 < C; c1++) {
                if (c1 == c0) continue;
                for (int c2 = 0; c2 < C; c2++) {
                    if (c2 == c0 || c2 == c1) continue;
                    long total = cost[0][c0] + cost[1][c1] + cost[2][c2];
                    if (total < ans) ans = total;
                }
            }
        }

        System.out.println(ans);
    }
}

